import{_ as t,o,c as s,l as n,t as r,N as a}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"git-fetch | x-cmd man (git man1) | Download objects and refs from another repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-fetch - Download objects and refs from another repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-fetch | x-cmd man (git man1) | Download objects and refs from another repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-fetch - Download objects and refs from another repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-fetch","category":"git man1","desc":"Download objects and refs from another repository"},"relativePath":"git/man1/git-fetch.md","filePath":"git/man1/git-fetch.md"}'),i={name:"git/man1/git-fetch.md"},l={class:"visually-hidden"},h=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-fetch - Download objects and refs from another repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refspec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">group</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --multiple</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">group</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)...]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Fetch branches and/or tags (collectively, &quot;refs&quot;) from one or more other repositories, along with the objects necessary to complete their histories. Remote-tracking branches are updated (see the description of &lt;refspec&gt; below for ways to control this behavior).</p><p>By default, any tag that points into the histories being fetched is also fetched; the effect is to fetch tags that point at branches that you are interested in. This default behavior can be changed by using the --tags or --no-tags options or by configuring remote.&lt;name&gt;.tagOpt. By using a refspec that fetches tags explicitly, you can fetch tags that do not point into branches you are interested in as well.</p><p><em>git fetch</em> can fetch from either a single named repository or URL, or from several repositories at once if &lt;group&gt; is given and there is a remotes.&lt;group&gt; entry in the configuration file. (See <strong>git-config</strong>(1)).</p><p>When no remote is specified, by default the <strong>origin</strong> remote will be used, unless there&#39;s an upstream branch configured for the current branch.</p><p>The names of refs that are fetched, together with the object names they point at, are written to <strong>.git/FETCH_HEAD</strong>. This information may be used by scripts or other git commands, such as <strong>git-pull</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--all</p><blockquote><p>Fetch all remotes.</p></blockquote><p>-a, --append</p><blockquote><p>Append ref names and object names of fetched refs to the existing contents of <strong>.git/FETCH_HEAD</strong>. Without this option old data in <strong>.git/FETCH_HEAD</strong> will be overwritten.</p></blockquote><p>--atomic</p><blockquote><p>Use an atomic transaction to update local refs. Either all refs are updated, or on error, no refs are updated.</p></blockquote><p>--depth=&lt;depth&gt;</p><blockquote><p>Limit fetching to the specified number of commits from the tip of each remote branch history. If fetching to a <em>shallow</em> repository created by <strong>git clone</strong> with <strong>--depth=&lt;depth&gt;</strong> option (see <strong>git-clone</strong>(1)), deepen or shorten the history to the specified number of commits. Tags for the deepened commits are not fetched.</p></blockquote><p>--deepen=&lt;depth&gt;</p><blockquote><p>Similar to --depth, except it specifies the number of commits from the current shallow boundary instead of from the tip of each remote branch history.</p></blockquote><p>--shallow-since=&lt;date&gt;</p><blockquote><p>Deepen or shorten the history of a shallow repository to include all reachable commits after &lt;date&gt;.</p></blockquote><p>--shallow-exclude=&lt;revision&gt;</p><blockquote><p>Deepen or shorten the history of a shallow repository to exclude commits reachable from a specified remote branch or tag. This option can be specified multiple times.</p></blockquote><p>--unshallow</p><blockquote><p>If the source repository is complete, convert a shallow repository to a complete one, removing all the limitations imposed by shallow repositories.</p><p>If the source repository is shallow, fetch as much as possible so that the current repository has the same history as the source repository.</p></blockquote><p>--update-shallow</p><blockquote><p>By default when fetching from a shallow repository, <strong>git fetch</strong> refuses refs that require updating .git/shallow. This option updates .git/shallow and accept such refs.</p></blockquote><p>--negotiation-tip=&lt;commit|glob&gt;</p><blockquote><p>By default, Git will report, to the server, commits reachable from all local refs to find common commits in an attempt to reduce the size of the to-be-received packfile. If specified, Git will only report commits reachable from the given tips. This is useful to speed up fetches when the user knows which local ref is likely to have commits in common with the upstream ref being fetched.</p><p>This option may be specified more than once; if so, Git will report commits reachable from any of the given commits.</p><p>The argument to this option may be a glob on ref names, a ref, or the (possibly abbreviated) SHA-1 of a commit. Specifying a glob is equivalent to specifying this option multiple times, one for each matching ref name.</p><p>See also the <strong>fetch.negotiationAlgorithm</strong> and <strong>push.negotiate</strong> configuration variables documented in <strong>git-config</strong>(1), and the <strong>--negotiate-only</strong> option below.</p></blockquote><p>--negotiate-only</p><blockquote><p>Do not fetch anything from the server, and instead print the ancestors of the provided *<em>--negotiation-tip=*</em> * arguments, which we have in common with the server.</p><p>This is incompatible with <strong>--recurse-submodules=[yes|on-demand]</strong>. Internally this is used to implement the <strong>push.negotiate</strong> option, see <strong>git-config</strong>(1).</p></blockquote><p>--dry-run</p><blockquote><p>Show what would be done, without making any changes.</p></blockquote><p>--[no-]write-fetch-head</p><blockquote><p>Write the list of remote refs fetched in the <strong>FETCH_HEAD</strong> file directly under <strong>$GIT_DIR</strong>. This is the default. Passing <strong>--no-write-fetch-head</strong> from the command line tells Git not to write the file. Under <strong>--dry-run</strong> option, the file is never written.</p></blockquote><p>-f, --force</p><blockquote><p>When <em>git fetch</em> is used with <strong>&lt;src&gt;:&lt;dst&gt;</strong> refspec it may refuse to update the local branch as discussed in the <strong>&lt;refspec&gt;</strong> part below. This option overrides that check.</p></blockquote><p>-k, --keep</p><blockquote><p>Keep downloaded pack.</p></blockquote><p>--multiple</p><blockquote><p>Allow several &lt;repository&gt; and &lt;group&gt; arguments to be specified. No &lt;refspec&gt;s may be specified.</p></blockquote><p>--[no-]auto-maintenance, --[no-]auto-gc</p><blockquote><p>Run <strong>git maintenance run --auto</strong> at the end to perform automatic repository maintenance if needed. (<strong>--[no-]auto-gc</strong> is a synonym.) This is enabled by default.</p></blockquote><p>--[no-]write-commit-graph</p><blockquote><p>Write a commit-graph after fetching. This overrides the config setting <strong>fetch.writeCommitGraph</strong>.</p></blockquote><p>--prefetch</p><blockquote><p>Modify the configured refspec to place all refs into the <strong>refs/prefetch/</strong> namespace. See the <strong>prefetch</strong> task in <strong>git-maintenance</strong>(1).</p></blockquote><p>-p, --prune</p><blockquote><p>Before fetching, remove any remote-tracking references that no longer exist on the remote. Tags are not subject to pruning if they are fetched only because of the default tag auto-following or due to a --tags option. However, if tags are fetched due to an explicit refspec (either on the command line or in the remote configuration, for example if the remote was cloned with the --mirror option), then they are also subject to pruning. Supplying <strong>--prune-tags</strong> is a shorthand for providing the tag refspec.</p><p>See the PRUNING section below for more details.</p></blockquote><p>-P, --prune-tags</p><blockquote><p>Before fetching, remove any local tags that no longer exist on the remote if <strong>--prune</strong> is enabled. This option should be used more carefully, unlike <strong>--prune</strong> it will remove any local references (local tags) that have been created. This option is a shorthand for providing the explicit tag refspec along with <strong>--prune</strong>, see the discussion about that in its documentation.</p><p>See the PRUNING section below for more details.</p></blockquote><p>-n, --no-tags</p><blockquote><p>By default, tags that point at objects that are downloaded from the remote repository are fetched and stored locally. This option disables this automatic tag following. The default behavior for a remote may be specified with the remote.&lt;name&gt;.tagOpt setting. See <strong>git-config</strong>(1).</p></blockquote><p>--refetch</p><blockquote><p>Instead of negotiating with the server to avoid transferring commits and associated objects that are already present locally, this option fetches all objects as a fresh clone would. Use this to reapply a partial clone filter from configuration or using <strong>--filter=</strong> when the filter definition has changed. Automatic post-fetch maintenance will perform object database pack consolidation to remove any duplicate objects.</p></blockquote><p>--refmap=&lt;refspec&gt;</p><blockquote><p>When fetching refs listed on the command line, use the specified refspec (can be given more than once) to map the refs to remote-tracking branches, instead of the values of <strong>remote.*.fetch</strong> configuration variables for the remote repository. Providing an empty <strong>&lt;refspec&gt;</strong> to the <strong>--refmap</strong> option causes Git to ignore the configured refspecs and rely entirely on the refspecs supplied as command-line arguments. See section on &quot;Configured Remote-tracking Branches&quot; for details.</p></blockquote><p>-t, --tags</p><blockquote><p>Fetch all tags from the remote (i.e., fetch remote tags *<em>refs/tags/*</em> * into local tags with the same name), in addition to whatever else would otherwise be fetched. Using this option alone does not subject tags to pruning, even if --prune is used (though tags may be pruned anyway if they are also the destination of an explicit refspec; see <strong>--prune</strong>).</p></blockquote><p>--recurse-submodules[=yes|on-demand|no]</p><blockquote><p>This option controls if and under what conditions new commits of submodules should be fetched too. When recursing through submodules, <strong>git fetch</strong> always attempts to fetch &quot;changed&quot; submodules, that is, a submodule that has commits that are referenced by a newly fetched superproject commit but are missing in the local submodule clone. A changed submodule can be fetched as long as it is present locally e.g. in <strong>$GIT_DIR/modules/</strong> (see <strong>gitsubmodules</strong>(7)); if the upstream adds a new submodule, that submodule cannot be fetched until it is cloned e.g. by <strong>git submodule update</strong>.</p><p>When set to <em>on-demand</em>, only changed submodules are fetched. When set to <em>yes</em>, all populated submodules are fetched and submodules that are both unpopulated and changed are fetched. When set to <em>no</em>, submodules are never fetched.</p><p>When unspecified, this uses the value of <strong>fetch.recurseSubmodules</strong> if it is set (see <strong>git-config</strong>(1)), defaulting to <em>on-demand</em> if unset. When this option is used without any value, it defaults to <em>yes</em>.</p></blockquote><p>-j, --jobs=&lt;n&gt;</p><blockquote><p>Number of parallel children to be used for all forms of fetching.</p><p>If the <strong>--multiple</strong> option was specified, the different remotes will be fetched in parallel. If multiple submodules are fetched, they will be fetched in parallel. To control them independently, use the config settings <strong>fetch.parallel</strong> and <strong>submodule.fetchJobs</strong> (see <strong>git-config</strong>(1)).</p><p>Typically, parallel recursive and multi-remote fetches will be faster. By default fetches are performed sequentially, not in parallel.</p></blockquote><p>--no-recurse-submodules</p><blockquote><p>Disable recursive fetching of submodules (this has the same effect as using the <strong>--recurse-submodules=no</strong> option).</p></blockquote><p>--set-upstream</p><blockquote><p>If the remote is fetched successfully, add upstream (tracking) reference, used by argument-less <strong>git-pull</strong>(1) and other commands. For more information, see <strong>branch.&lt;name&gt;.merge</strong> and <strong>branch.&lt;name&gt;.remote</strong> in <strong>git-config</strong>(1).</p></blockquote><p>--submodule-prefix=&lt;path&gt;</p><blockquote><p>Prepend &lt;path&gt; to paths printed in informative messages such as &quot;Fetching submodule foo&quot;. This option is used internally when recursing over submodules.</p></blockquote><p>--recurse-submodules-default=[yes|on-demand]</p><blockquote><p>This option is used internally to temporarily provide a non-negative default value for the --recurse-submodules option. All other methods of configuring fetch&#39;s submodule recursion (such as settings in <strong>gitmodules</strong>(5) and <strong>git-config</strong>(1)) override this option, as does specifying --[no-]recurse-submodules directly.</p></blockquote><p>-u, --update-head-ok</p><blockquote><p>By default <em>git fetch</em> refuses to update the head which corresponds to the current branch. This flag disables the check. This is purely for the internal use for <em>git pull</em> to communicate with <em>git fetch</em>, and unless you are implementing your own Porcelain you are not supposed to use it.</p></blockquote><p>--upload-pack &lt;upload-pack&gt;</p><blockquote><p>When given, and the repository to fetch from is handled by <em>git fetch-pack</em>, <strong>--exec=&lt;upload-pack&gt;</strong> is passed to the command to specify non-default path for the command run on the other end.</p></blockquote><p>-q, --quiet</p><blockquote><p>Pass --quiet to git-fetch-pack and silence any other internally used git commands. Progress is not reported to the standard error stream.</p></blockquote><p>-v, --verbose</p><blockquote><p>Be verbose.</p></blockquote><p>--progress</p><blockquote><p>Progress status is reported on the standard error stream by default when it is attached to a terminal, unless -q is specified. This flag forces progress status even if the standard error stream is not directed to a terminal.</p></blockquote><p>-o &lt;option&gt;, --server-option=&lt;option&gt;</p><blockquote><p>Transmit the given string to the server when communicating using protocol version 2. The given string must not contain a NUL or LF character. The server&#39;s handling of server options, including unknown ones, is server-specific. When multiple <strong>--server-option=&lt;option&gt;</strong> are given, they are all sent to the other side in the order listed on the command line.</p></blockquote><p>--show-forced-updates</p><blockquote><p>By default, git checks if a branch is force-updated during fetch. This can be disabled through fetch.showForcedUpdates, but the --show-forced-updates option guarantees this check occurs. See <strong>git-config</strong>(1).</p></blockquote><p>--no-show-forced-updates</p><blockquote><p>By default, git checks if a branch is force-updated during fetch. Pass --no-show-forced-updates or set fetch.showForcedUpdates to false to skip this check for performance reasons. If used during <em>git-pull</em> the --ff-only option will still check for forced updates before attempting a fast-forward update. See <strong>git-config</strong>(1).</p></blockquote><p>-4, --ipv4</p><blockquote><p>Use IPv4 addresses only, ignoring IPv6 addresses.</p></blockquote><p>-6, --ipv6</p><blockquote><p>Use IPv6 addresses only, ignoring IPv4 addresses.</p></blockquote><p>&lt;repository&gt;</p><blockquote><p>The &quot;remote&quot; repository that is the source of a fetch or pull operation. This parameter can be either a URL (see the section GIT URLS below) or the name of a remote (see the section REMOTES below).</p></blockquote><p>&lt;group&gt;</p><blockquote><p>A name referring to a list of repositories as the value of remotes.&lt;group&gt; in the configuration file. (See <strong>git-config</strong>(1)).</p></blockquote><p>&lt;refspec&gt;</p><blockquote><p>Specifies which refs to fetch and which local refs to update. When no &lt;refspec&gt;s appear on the command line, the refs to fetch are read from <strong>remote.&lt;repository&gt;.fetch</strong> variables instead (see CONFIGURED REMOTE-TRACKING BRANCHES below).</p><p>The format of a &lt;refspec&gt; parameter is an optional plus <strong>+</strong>, followed by the source &lt;src&gt;, followed by a colon <strong>:</strong>, followed by the destination ref &lt;dst&gt;. The colon can be omitted when &lt;dst&gt; is empty. &lt;src&gt; is typically a ref, but it can also be a fully spelled hex object name.</p><p>A &lt;refspec&gt; may contain a *<em>*</em> * in its &lt;src&gt; to indicate a simple pattern match. Such a refspec functions like a glob that matches any ref with the same prefix. A pattern &lt;refspec&gt; must have a *<em>*</em> * in both the &lt;src&gt; and &lt;dst&gt;. It will map refs to the destination by replacing the *<em>*</em> * with the contents matched from the source.</p><p>If a refspec is prefixed by <strong>^</strong>, it will be interpreted as a negative refspec. Rather than specifying which refs to fetch or which local refs to update, such a refspec will instead specify refs to exclude. A ref will be considered to match if it matches at least one positive refspec, and does not match any negative refspec. Negative refspecs can be useful to restrict the scope of a pattern refspec so that it will not include specific refs. Negative refspecs can themselves be pattern refspecs. However, they may only contain a &lt;src&gt; and do not specify a &lt;dst&gt;. Fully spelled out hex object names are also not supported.</p><p><strong>tag &lt;tag&gt;</strong> means the same as <strong>refs/tags/&lt;tag&gt;:refs/tags/&lt;tag&gt;</strong>; it requests fetching everything up to the given tag.</p><p>The remote ref that matches &lt;src&gt; is fetched, and if &lt;dst&gt; is not an empty string, an attempt is made to update the local ref that matches it.</p><p>Whether that update is allowed without <strong>--force</strong> depends on the ref namespace it&#39;s being fetched to, the type of object being fetched, and whether the update is considered to be a fast-forward. Generally, the same rules apply for fetching as when pushing, see the <strong>&lt;refspec&gt;...</strong> section of <strong>git-push</strong>(1) for what those are. Exceptions to those rules particular to <em>git fetch</em> are noted below.</p><p>Until Git version 2.20, and unlike when pushing with <strong>git-push</strong>(1), any updates to *<em>refs/tags/*</em> * would be accepted without <strong>+</strong> in the refspec (or <strong>--force</strong>). When fetching, we promiscuously considered all tag updates from a remote to be forced fetches. Since Git version 2.20, fetching to update *<em>refs/tags/*</em> * works the same way as when pushing. I.e. any updates will be rejected without <strong>+</strong> in the refspec (or <strong>--force</strong>).</p><p>Unlike when pushing with <strong>git-push</strong>(1), any updates outside of *<em>refs/{tags,heads}/*</em> * will be accepted without <strong>+</strong> in the refspec (or <strong>--force</strong>), whether that&#39;s swapping e.g. a tree object for a blob, or a commit for another commit that&#39;s doesn&#39;t have the previous commit as an ancestor etc.</p><p>Unlike when pushing with <strong>git-push</strong>(1), there is no configuration which&#39;ll amend these rules, and nothing like a <strong>pre-fetch</strong> hook analogous to the <strong>pre-receive</strong> hook.</p><p>As with pushing with <strong>git-push</strong>(1), all of the rules described above about what&#39;s not allowed as an update can be overridden by adding an the optional leading <strong>+</strong> to a refspec (or using <strong>--force</strong> command line option). The only exception to this is that no amount of forcing will make the *<em>refs/heads/*</em> * namespace accept a non-commit object.</p><blockquote><p><br> &gt; &gt; <strong>Note</strong></p><p><br> &gt; &gt; When the remote branch you want to fetch is known to be rewound and rebased regularly, it is expected that its new tip will not be descendant of its previous tip (as stored in your remote-tracking branch the last time you fetched). You would want to use the <strong>+</strong> sign to indicate non-fast-forward updates will be needed for such branches. There is no way to determine or declare that a branch will be made available in a repository with this behavior; the pulling user simply must know this is the expected usage pattern for a branch.</p></blockquote></blockquote><p>--stdin</p><blockquote><p>Read refspecs, one per line, from stdin in addition to those provided as arguments. The &quot;tag &lt;name&gt;&quot; format is not supported.</p></blockquote><h2 id="git-urls" tabindex="-1">GIT URLS <a class="header-anchor" href="#git-urls" aria-label="Permalink to &quot;GIT URLS&quot;">​</a></h2><p>In general, URLs contain information about the transport protocol, the address of the remote server, and the path to the repository. Depending on the transport protocol, some of this information may be absent.</p><p>Git supports ssh, git, http, and https protocols (in addition, ftp, and ftps can be used for fetching, but this is inefficient and deprecated; do not use it).</p><p>The native transport (i.e. git:// URL) does no authentication and should be used with caution on unsecured networks.</p><p>The following syntaxes may be used with them:</p><blockquote><p>·</p><p>ssh://[user@]host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>git://host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>http[s]😕/host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>ftp[s]😕/host.xz[:port]/path/to/repo.git/</p></blockquote><p>An alternative scp-like syntax may also be used with the ssh protocol:</p><blockquote><p>·</p><p>[user@]host.xz:path/to/repo.git/</p></blockquote><p>This syntax is only recognized if there are no slashes before the first colon. This helps differentiate a local path that contains a colon. For example the local path <strong>foo:bar</strong> could be specified as an absolute path or <strong>./foo:bar</strong> to avoid being misinterpreted as an ssh url.</p><p>The ssh and git protocols additionally support ~username expansion:</p><blockquote><p>·</p><p>ssh://[user@]host.xz[:port]/~[user]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>git://host.xz[:port]/~[user]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>[user@]host.xz:/~[user]/path/to/repo.git/</p></blockquote><p>For local repositories, also supported by Git natively, the following syntaxes may be used:</p><blockquote><p>·</p><p>/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>file:///path/to/repo.git/</p></blockquote><p>These two syntaxes are mostly equivalent, except when cloning, when the former implies --local option. See <strong>git-clone</strong>(1) for details.</p><p><em>git clone</em>, <em>git fetch</em> and <em>git pull</em>, but not <em>git push</em>, will also accept a suitable bundle file. See <strong>git-bundle</strong>(1).</p><p>When Git doesn&#39;t know how to handle a certain transport protocol, it attempts to use the <em>remote-&lt;transport&gt;</em> remote helper, if one exists. To explicitly request a remote helper, the following syntax may be used:</p><blockquote><p>·</p><p>&lt;transport&gt;::&lt;address&gt;</p></blockquote><p>where &lt;address&gt; may be a path, a server and path, or an arbitrary URL-like string recognized by the specific remote helper being invoked. See <strong>gitremote-helpers</strong>(7) for details.</p><p>If there are a large number of similarly-named remote repositories and you want to use a different format for them (such that the URLs you use will be rewritten into URLs that work), you can create a configuration section of the form:</p><blockquote><pre><code>        [url &quot;&lt;actual url base&gt;&quot;]
                insteadOf = &lt;other url base&gt;
</code></pre></blockquote><p>For example, with this:</p><blockquote><pre><code>        [url &quot;git://git.host.xz/&quot;]
                insteadOf = host.xz:/path/to/
                insteadOf = work:
</code></pre></blockquote><p>a URL like &quot;work:repo.git&quot; or like &quot;host.xz:/path/to/repo.git&quot; will be rewritten in any context that takes a URL to be &quot;git://git.host.xz/repo.git&quot;.</p><p>If you want to rewrite URLs for push only, you can create a configuration section of the form:</p><blockquote><pre><code>        [url &quot;&lt;actual url base&gt;&quot;]
                pushInsteadOf = &lt;other url base&gt;
</code></pre></blockquote><p>For example, with this:</p><blockquote><pre><code>        [url &quot;ssh://example.org/&quot;]
                pushInsteadOf = git://example.org/
</code></pre></blockquote><p>a URL like &quot;git://example.org/path/to/repo.git&quot; will be rewritten to &quot;ssh://example.org/path/to/repo.git&quot; for pushes, but pulls will still use the original URL.</p><h2 id="remotes" tabindex="-1">REMOTES <a class="header-anchor" href="#remotes" aria-label="Permalink to &quot;REMOTES&quot;">​</a></h2><p>The name of one of the following can be used instead of a URL as <strong>&lt;repository&gt;</strong> argument:</p><blockquote><p>·</p><p>a remote in the Git configuration file: <strong>$GIT_DIR/config</strong>,</p></blockquote><blockquote><p>·</p><p>a file in the <strong>$GIT_DIR/remotes</strong> directory, or</p></blockquote><blockquote><p>·</p><p>a file in the <strong>$GIT_DIR/branches</strong> directory.</p></blockquote><p>All of these also allow you to omit the refspec from the command line because they each contain a refspec which git will use by default.</p><h3 id="named-remote-in-configuration-file" tabindex="-1">Named remote in configuration file <a class="header-anchor" href="#named-remote-in-configuration-file" aria-label="Permalink to &quot;Named remote in configuration file&quot;">​</a></h3><p>You can choose to provide the name of a remote which you had previously configured using <strong>git-remote</strong>(1), <strong>git-config</strong>(1) or even by a manual edit to the <strong>$GIT_DIR/config</strong> file. The URL of this remote will be used to access the repository. The refspec of this remote will be used by default when you do not provide a refspec on the command line. The entry in the config file would appear like this:</p><blockquote><pre><code>        [remote &quot;&lt;name&gt;&quot;]
                url = &lt;URL&gt;
                pushurl = &lt;pushurl&gt;
                push = &lt;refspec&gt;
                fetch = &lt;refspec&gt;
</code></pre></blockquote><p>The <strong>&lt;pushurl&gt;</strong> is used for pushes only. It is optional and defaults to <strong>&lt;URL&gt;</strong>. Pushing to a remote affects all defined pushurls or to all defined urls if no pushurls are defined. Fetch, however, will only fetch from the first defined url if muliple urls are defined.</p><h3 id="named-file-in-git-dir-remotes" tabindex="-1">Named file in <strong>$GIT_DIR/remotes</strong> <a class="header-anchor" href="#named-file-in-git-dir-remotes" aria-label="Permalink to &quot;Named file in **\\$GIT_DIR/remotes**&quot;">​</a></h3><p>You can choose to provide the name of a file in <strong>$GIT_DIR/remotes</strong>. The URL in this file will be used to access the repository. The refspec in this file will be used as default when you do not provide a refspec on the command line. This file should have the following format:</p><blockquote><pre><code>        URL: one of the above URL format
        Push: &lt;refspec&gt;
        Pull: &lt;refspec&gt;
</code></pre></blockquote><p><strong>Push:</strong> lines are used by <em>git push</em> and <strong>Pull:</strong> lines are used by <em>git pull</em> and <em>git fetch</em>. Multiple <strong>Push:</strong> and <strong>Pull:</strong> lines may be specified for additional branch mappings.</p><h3 id="named-file-in-git-dir-branches" tabindex="-1">Named file in <strong>$GIT_DIR/branches</strong> <a class="header-anchor" href="#named-file-in-git-dir-branches" aria-label="Permalink to &quot;Named file in **\\$GIT_DIR/branches**&quot;">​</a></h3><p>You can choose to provide the name of a file in <strong>$GIT_DIR/branches</strong>. The URL in this file will be used to access the repository. This file should have the following format:</p><blockquote><pre><code>        &lt;URL&gt;#&lt;head&gt;
</code></pre></blockquote><p><strong>&lt;URL&gt;</strong> is required; <strong>#&lt;head&gt;</strong> is optional.</p><p>Depending on the operation, git will use one of the following refspecs, if you don&#39;t provide one on the command line. <strong>&lt;branch&gt;</strong> is the name of this file in <strong>$GIT_DIR/branches</strong> and <strong>&lt;head&gt;</strong> defaults to <strong>master</strong>.</p><p>git fetch uses:</p><blockquote><pre><code>        refs/heads/&lt;head&gt;:refs/heads/&lt;branch&gt;
</code></pre></blockquote><p>git push uses:</p><blockquote><pre><code>        HEAD:refs/heads/&lt;head&gt;
</code></pre></blockquote><h2 id="configured-remote-tracking-branches" tabindex="-1">CONFIGURED REMOTE-TRACKING BRANCHES <a class="header-anchor" href="#configured-remote-tracking-branches" aria-label="Permalink to &quot;CONFIGURED REMOTE-TRACKING BRANCHES&quot;">​</a></h2><p>You often interact with the same remote repository by regularly and repeatedly fetching from it. In order to keep track of the progress of such a remote repository, <strong>git fetch</strong> allows you to configure <strong>remote.&lt;repository&gt;.fetch</strong> configuration variables.</p><p>Typically such a variable may look like this:</p><blockquote><pre><code>[remote &quot;origin&quot;]
        fetch = +refs/heads/*:refs/remotes/origin/*
</code></pre></blockquote><p>This configuration is used in two ways:</p><blockquote><p>·</p><p>When <strong>git fetch</strong> is run without specifying what branches and/or tags to fetch on the command line, e.g. <strong>git fetch origin</strong> or <strong>git fetch</strong>, <strong>remote.&lt;repository&gt;.fetch</strong> values are used as the refspecs---they specify which refs to fetch and which local refs to update. The example above will fetch all branches that exist in the <strong>origin</strong> (i.e. any ref that matches the left-hand side of the value, *<em>refs/heads/*</em> *) and update the corresponding remote-tracking branches in the *<em>refs/remotes/origin/*</em> * hierarchy.</p></blockquote><blockquote><p>·</p><p>When <strong>git fetch</strong> is run with explicit branches and/or tags to fetch on the command line, e.g. <strong>git fetch origin master</strong>, the &lt;refspec&gt;s given on the command line determine what are to be fetched (e.g. <strong>master</strong> in the example, which is a short-hand for <strong>master:</strong>, which in turn means &quot;fetch the <em>master</em> branch but I do not explicitly say what remote-tracking branch to update with it from the command line&quot;), and the example command will fetch <em>only</em> the <em>master</em> branch. The <strong>remote.&lt;repository&gt;.fetch</strong> values determine which remote-tracking branch, if any, is updated. When used in this way, the <strong>remote.&lt;repository&gt;.fetch</strong> values do not have any effect in deciding <em>what</em> gets fetched (i.e. the values are not used as refspecs when the command-line lists refspecs); they are only used to decide <em>where</em> the refs that are fetched are stored by acting as a mapping.</p></blockquote><p>The latter use of the <strong>remote.&lt;repository&gt;.fetch</strong> values can be overridden by giving the <strong>--refmap=&lt;refspec&gt;</strong> parameter(s) on the command line.</p><h2 id="pruning" tabindex="-1">PRUNING <a class="header-anchor" href="#pruning" aria-label="Permalink to &quot;PRUNING&quot;">​</a></h2><p>Git has a default disposition of keeping data unless it&#39;s explicitly thrown away; this extends to holding onto local references to branches on remotes that have themselves deleted those branches.</p><p>If left to accumulate, these stale references might make performance worse on big and busy repos that have a lot of branch churn, and e.g. make the output of commands like <strong>git branch -a --contains &lt;commit&gt;</strong> needlessly verbose, as well as impacting anything else that&#39;ll work with the complete set of known references.</p><p>These remote-tracking references can be deleted as a one-off with either of:</p><blockquote><pre><code># While fetching
$ git fetch --prune &lt;name&gt;

# Only prune, don&#39;t fetch
$ git remote prune &lt;name&gt;
</code></pre></blockquote><p>To prune references as part of your normal workflow without needing to remember to run that, set <strong>fetch.prune</strong> globally, or <strong>remote.&lt;name&gt;.prune</strong> per-remote in the config. See <strong>git-config</strong>(1).</p><p>Here&#39;s where things get tricky and more specific. The pruning feature doesn&#39;t actually care about branches, instead it&#39;ll prune local ←→ remote-references as a function of the refspec of the remote (see <strong>&lt;refspec&gt;</strong> and CONFIGURED REMOTE-TRACKING BRANCHES above).</p><p>Therefore if the refspec for the remote includes e.g. *<em>refs/tags/*:refs/tags/*</em> *, or you manually run e.g. <strong>git fetch --prune &lt;name&gt; &quot;refs/tags/*:refs/tags/*&quot;</strong> it won&#39;t be stale remote tracking branches that are deleted, but any local tag that doesn&#39;t exist on the remote.</p><p>This might not be what you expect, i.e. you want to prune remote <strong>&lt;name&gt;</strong>, but also explicitly fetch tags from it, so when you fetch from it you delete all your local tags, most of which may not have come from the <strong>&lt;name&gt;</strong> remote in the first place.</p><p>So be careful when using this with a refspec like *<em>refs/tags/*:refs/tags/*</em> *, or any other refspec which might map references from multiple remotes to the same local namespace.</p><p>Since keeping up-to-date with both branches and tags on the remote is a common use-case the <strong>--prune-tags</strong> option can be supplied along with <strong>--prune</strong> to prune local tags that don&#39;t exist on the remote, and force-update those tags that differ. Tag pruning can also be enabled with <strong>fetch.pruneTags</strong> or <strong>remote.&lt;name&gt;.pruneTags</strong> in the config. See <strong>git-config</strong>(1).</p><p>The <strong>--prune-tags</strong> option is equivalent to having *<em>refs/tags/*:refs/tags/*</em> * declared in the refspecs of the remote. This can lead to some seemingly strange interactions:</p><blockquote><pre><code># These both fetch tags
$ git fetch --no-tags origin &#39;refs/tags/*:refs/tags/*&#39;
$ git fetch --no-tags --prune-tags origin
</code></pre></blockquote><p>The reason it doesn&#39;t error out when provided without <strong>--prune</strong> or its config versions is for flexibility of the configured versions, and to maintain a 1=1 mapping between what the command line flags do, and what the configuration versions do.</p><p>It&#39;s reasonable to e.g. configure <strong>fetch.pruneTags=true</strong> in <strong>~/.gitconfig</strong> to have tags pruned whenever <strong>git fetch --prune</strong> is run, without making every invocation of <strong>git fetch</strong> without <strong>--prune</strong> an error.</p><p>Pruning tags with <strong>--prune-tags</strong> also works when fetching a URL instead of a named remote. These will all prune tags not found on origin:</p><blockquote><pre><code>$ git fetch origin --prune --prune-tags
$ git fetch origin --prune &#39;refs/tags/*:refs/tags/*&#39;
$ git fetch &lt;url of origin&gt; --prune --prune-tags
$ git fetch &lt;url of origin&gt; --prune &#39;refs/tags/*:refs/tags/*&#39;
</code></pre></blockquote><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>The output of &quot;git fetch&quot; depends on the transport method used; this section describes the output when fetching over the Git protocol (either locally or via ssh) and Smart HTTP protocol.</p><p>The status of the fetch is output in tabular form, with each line representing the status of a single ref. Each line is of the form:</p><blockquote><pre><code> &lt;flag&gt; &lt;summary&gt; &lt;from&gt; -&gt; &lt;to&gt; [&lt;reason&gt;]
</code></pre></blockquote><p>The status of up-to-date refs is shown only if the --verbose option is used.</p><p>In compact output mode, specified with configuration variable fetch.output, if either entire <strong>&lt;from&gt;</strong> or <strong>&lt;to&gt;</strong> is found in the other string, it will be substituted with *<em>*</em> * in the other string. For example, <strong>master -&gt; origin/master</strong> becomes *<em>master -&gt; origin/*</em> *.</p><p>flag</p><blockquote><p>A single character indicating the status of the ref:</p><p>(space)</p><blockquote><p>for a successfully fetched fast-forward;</p></blockquote><p><strong>+</strong></p><blockquote><p>for a successful forced update;</p></blockquote><p><strong>-</strong></p><blockquote><p>for a successfully pruned ref;</p></blockquote><p><strong>t</strong></p><blockquote><p>for a successful tag update;</p></blockquote><p>*<em>*</em> *</p><blockquote><p>for a successfully fetched new ref;</p></blockquote><p><strong>!</strong></p><blockquote><p>for a ref that was rejected or failed to update; and</p></blockquote><p><strong>=</strong></p><blockquote><p>for a ref that was up to date and did not need fetching.</p></blockquote></blockquote><p>summary</p><blockquote><p>For a successfully fetched ref, the summary shows the old and new values of the ref in a form suitable for using as an argument to <strong>git log</strong> (this is <strong>&lt;old&gt;..&lt;new&gt;</strong> in most cases, and <strong>&lt;old&gt;...&lt;new&gt;</strong> for forced non-fast-forward updates).</p></blockquote><p>from</p><blockquote><p>The name of the remote ref being fetched from, minus its <strong>refs/&lt;type&gt;/</strong> prefix. In the case of deletion, the name of the remote ref is &quot;(none)&quot;.</p></blockquote><p>to</p><blockquote><p>The name of the local ref being updated, minus its <strong>refs/&lt;type&gt;/</strong> prefix.</p></blockquote><p>reason</p><blockquote><p>A human-readable explanation. In the case of successfully fetched refs, no explanation is needed. For a failed ref, the reason for failure is described.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p>·</p><p>Update the remote-tracking branches:</p><blockquote><pre><code>$ git fetch origin
</code></pre></blockquote><p>The above command copies all branches from the remote <strong>refs/heads/</strong> namespace and stores them to the local <strong>refs/remotes/origin/</strong> namespace, unless the <strong>remote.&lt;repository&gt;.fetch</strong> option is used to specify a non-default refspec.</p></blockquote><blockquote><p>·</p><p>Using refspecs explicitly:</p><blockquote><pre><code>$ git fetch origin +seen:seen maint:tmp
</code></pre></blockquote><p>This updates (or creates, as necessary) branches <strong>seen</strong> and <strong>tmp</strong> in the local repository by fetching from the branches (respectively) <strong>seen</strong> and <strong>maint</strong> from the remote repository.</p><p>The <strong>seen</strong> branch will be updated even if it does not fast-forward, because it is prefixed with a plus sign; <strong>tmp</strong> will not be.</p></blockquote><blockquote><p>·</p><p>Peek at a remote&#39;s branch, without configuring the remote in your local repository:</p><blockquote><pre><code>$ git fetch git://git.kernel.org/pub/scm/git/git.git maint
$ git log FETCH_HEAD
</code></pre></blockquote><p>The first command fetches the <strong>maint</strong> branch from the repository at <strong>git://git.kernel.org/pub/scm/git/git.git</strong> and the second command uses <strong>FETCH_HEAD</strong> to examine the branch with <strong>git-log</strong>(1). The fetched objects will eventually be removed by git&#39;s built-in housekeeping (see <strong>git-gc</strong>(1)).</p></blockquote><h2 id="security" tabindex="-1">SECURITY <a class="header-anchor" href="#security" aria-label="Permalink to &quot;SECURITY&quot;">​</a></h2><p>The fetch and push protocols are not designed to prevent one side from stealing data from the other repository that was not intended to be shared. If you have private data that you need to protect from a malicious peer, your best option is to store it in another repository. This applies to both clients and servers. In particular, namespaces on a server are not effective for read access control; you should only grant read access to a namespace to clients that you would trust with read access to the entire repository.</p><p>The known attack vectors are as follows:</p><blockquote><p>1.</p><p>The victim sends &quot;have&quot; lines advertising the IDs of objects it has that are not explicitly intended to be shared but can be used to optimize the transfer if the peer also has them. The attacker chooses an object ID X to steal and sends a ref to X, but isn&#39;t required to send the content of X because the victim already has it. Now the victim believes that the attacker has X, and it sends the content of X back to the attacker later. (This attack is most straightforward for a client to perform on a server, by creating a ref to X in the namespace the client has access to and then fetching it. The most likely way for a server to perform it on a client is to &quot;merge&quot; X into a public branch and hope that the user does additional work on this branch and pushes it back to the server without noticing the merge.)</p></blockquote><blockquote><p>2.</p><p>As in #1, the attacker chooses an object ID X to steal. The victim sends an object Y that the attacker already has, and the attacker falsely claims to have X and not Y, so the victim sends Y as a delta against X. The delta reveals regions of X that are similar to Y to the attacker.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>fetch.recurseSubmodules</p><blockquote><p>This option controls whether <strong>git fetch</strong> (and the underlying fetch in <strong>git pull</strong>) will recursively fetch into populated submodules. This option can be set either to a boolean value or to <em>on-demand</em>. Setting it to a boolean changes the behavior of fetch and pull to recurse unconditionally into submodules when set to true or to not recurse at all when set to false. When set to <em>on-demand</em>, fetch and pull will only recurse into a populated submodule when its superproject retrieves a commit that updates the submodule&#39;s reference. Defaults to <em>on-demand</em>, or to the value of <em>submodule.recurse</em> if set.</p></blockquote><p>fetch.fsckObjects</p><blockquote><p>If it is set to true, git-fetch-pack will check all fetched objects. See <strong>transfer.fsckObjects</strong> for what&#39;s checked. Defaults to false. If not set, the value of <strong>transfer.fsckObjects</strong> is used instead.</p></blockquote><p>fetch.fsck.&lt;msg-id&gt;</p><blockquote><p>Acts like <strong>fsck.&lt;msg-id&gt;</strong>, but is used by <strong>git-fetch-pack</strong>(1) instead of <strong>git-fsck</strong>(1). See the <strong>fsck.&lt;msg-id&gt;</strong> documentation for details.</p></blockquote><p>fetch.fsck.skipList</p><blockquote><p>Acts like <strong>fsck.skipList</strong>, but is used by <strong>git-fetch-pack</strong>(1) instead of <strong>git-fsck</strong>(1). See the <strong>fsck.skipList</strong> documentation for details.</p></blockquote><p>fetch.unpackLimit</p><blockquote><p>If the number of objects fetched over the Git native transfer is below this limit, then the objects will be unpacked into loose object files. However if the number of received objects equals or exceeds this limit then the received pack will be stored as a pack, after adding any missing delta bases. Storing the pack from a push can make the push operation complete faster, especially on slow filesystems. If not set, the value of <strong>transfer.unpackLimit</strong> is used instead.</p></blockquote><p>fetch.prune</p><blockquote><p>If true, fetch will automatically behave as if the <strong>--prune</strong> option was given on the command line. See also <strong>remote.&lt;name&gt;.prune</strong> and the PRUNING section of <strong>git-fetch</strong>(1).</p></blockquote><p>fetch.pruneTags</p><blockquote><p>If true, fetch will automatically behave as if the *<em>refs/tags/*:refs/tags/*</em> * refspec was provided when pruning, if not set already. This allows for setting both this option and <strong>fetch.prune</strong> to maintain a 1=1 mapping to upstream refs. See also <strong>remote.&lt;name&gt;.pruneTags</strong> and the PRUNING section of <strong>git-fetch</strong>(1).</p></blockquote><p>fetch.output</p><blockquote><p>Control how ref update status is printed. Valid values are <strong>full</strong> and <strong>compact</strong>. Default value is <strong>full</strong>. See section OUTPUT in <strong>git-fetch</strong>(1) for detail.</p></blockquote><p>fetch.negotiationAlgorithm</p><blockquote><p>Control how information about the commits in the local repository is sent when negotiating the contents of the packfile to be sent by the server. Set to &quot;consecutive&quot; to use an algorithm that walks over consecutive commits checking each one. Set to &quot;skipping&quot; to use an algorithm that skips commits in an effort to converge faster, but may result in a larger-than-necessary packfile; or set to &quot;noop&quot; to not send any information at all, which will almost certainly result in a larger-than-necessary packfile, but will skip the negotiation step. Set to &quot;default&quot; to override settings made previously and use the default behaviour. The default is normally &quot;consecutive&quot;, but if <strong>feature.experimental</strong> is true, then the default is &quot;skipping&quot;. Unknown values will cause <em>git fetch</em> to error out.</p><p>See also the <strong>--negotiate-only</strong> and <strong>--negotiation-tip</strong> options to <strong>git-fetch</strong>(1).</p></blockquote><p>fetch.showForcedUpdates</p><blockquote><p>Set to false to enable <strong>--no-show-forced-updates</strong> in <strong>git-fetch</strong>(1) and <strong>git-pull</strong>(1) commands. Defaults to true.</p></blockquote><p>fetch.parallel</p><blockquote><p>Specifies the maximal number of fetch operations to be run in parallel at a time (submodules, or remotes when the <strong>--multiple</strong> option of <strong>git-fetch</strong>(1) is in effect).</p><p>A value of 0 will give some reasonable default. If unset, it defaults to 1.</p><p>For submodules, this setting can be overridden using the <strong>submodule.fetchJobs</strong> config setting.</p></blockquote><p>fetch.writeCommitGraph</p><blockquote><p>Set to true to write a commit-graph after every <strong>git fetch</strong> command that downloads a pack-file from a remote. Using the <strong>--split</strong> option, most executions will create a very small commit-graph file on top of the existing commit-graph file(s). Occasionally, these files will merge and the write may take longer. Having an updated commit-graph file helps performance of many Git commands, including <strong>git merge-base</strong>, <strong>git push -f</strong>, and <strong>git log --graph</strong>. Defaults to false.</p></blockquote><p>fetch.bundleURI</p><blockquote><p>This value stores a URI for downloading Git object data from a bundle URI before performing an incremental fetch from the origin Git server. This is similar to how the <strong>--bundle-uri</strong> option behaves in <strong>git-clone</strong>(1). <strong>git clone --bundle-uri</strong> will set the <strong>fetch.bundleURI</strong> value if the supplied bundle URI contains a bundle list that is organized for incremental fetches.</p><p>If you modify this value and your repository has a <strong>fetch.bundleCreationToken</strong> value, then remove that <strong>fetch.bundleCreationToken</strong> value before fetching from the new bundle URI.</p></blockquote><p>fetch.bundleCreationToken</p><blockquote><p>When using <strong>fetch.bundleURI</strong> to fetch incrementally from a bundle list that uses the &quot;creationToken&quot; heuristic, this config value stores the maximum <strong>creationToken</strong> value of the downloaded bundles. This value is used to prevent downloading bundles in the future if the advertised <strong>creationToken</strong> is not strictly larger than this value.</p><p>The creation token values are chosen by the provider serving the specific bundle URI. If you modify the URI at <strong>fetch.bundleURI</strong>, then be sure to remove the value for the <strong>fetch.bundleCreationToken</strong> value before fetching.</p></blockquote><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Using --recurse-submodules can only fetch new commits in submodules that are present locally e.g. in <strong>$GIT_DIR/modules/</strong>. If the upstream adds a new submodule, that submodule cannot be fetched until it is cloned e.g. by <strong>git submodule update</strong>. This is expected to be fixed in a future Git version.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-pull</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,244);function p(e,c,g,u,d,f){return o(),s("div",null,[n("h1",l,r(e.$params.man),1),h])}const k=t(i,[["render",p]]);export{b as __pageData,k as default};
